export type Booking = {
  id: number; lab: string; seats: number; purpose: string;
  status: 'PENDING' | 'CONFIRMED' | 'CANCELLED'; createdAt: string;
};

// Omit the server-owned fields — a create DTO that tracks Booking.
export type CreateBooking = Omit<Booking, 'id' | 'status' | 'createdAt'>;

export function createBooking(input: CreateBooking): Booking {
  return { ...input, id: 1, status: 'PENDING', createdAt: '2027-03-03T06:00:00Z' };
}

import { createBooking } from '../src/create.ts';
const b = createBooking({ lab: 'BE-201', seats: 40, purpose: 'Lab' }); // no server fields
export { b };

import type { CreateBooking } from '../src/create.ts';
const bad: CreateBooking = { lab: 'BE-201', seats: 40, purpose: 'Lab', id: 99 }; // expect TS2353
export { bad };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createBooking } from '../src/create.ts';
test('createBooking', () => { const b = createBooking({ lab: 'BE-201', seats: 40, purpose: 'Lab' }); assert.equal(b.id, 1); assert.equal(b.status, 'PENDING'); });

