export type User = { id: number; name: string; email: string; passwordHash: string };

// Wrong: the public view still has the password hash.
export type PublicUser = User;

export function toPublic(u: User): PublicUser {
  return u;
}

import { toPublic } from '../src/public.ts';
const p = toPublic({ id: 1, name: 'An', email: 'a@x.vn', passwordHash: 'x' });
const name: string = p.name;
export { name };

import type { PublicUser } from '../src/public.ts';
function show(u: PublicUser) { return u.passwordHash; } // expect TS2339
export { show };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { toPublic } from '../src/public.ts';
test('toPublic drops the hash', () => { const p = toPublic({ id: 1, name: 'An', email: 'a@x.vn', passwordHash: 'secret' }); assert.ok(!('passwordHash' in p)); assert.equal(p.name, 'An'); });

